import{_ as e,o as a,c as i,ag as o}from"./chunks/framework.CVaJrGn7.js";const h=JSON.parse('{"title":"@guideflow/analytics","description":"@guideflow/analytics — tour event collection with privacy controls, five transports, and deterministic A/B variant assignment for GuideFlow.","frontmatter":{"description":"@guideflow/analytics — tour event collection with privacy controls, five transports, and deterministic A/B variant assignment for GuideFlow.","keywords":"@guideflow/analytics, product tour analytics, A/B tour testing, tour event tracking","head":[["link",{"rel":"canonical","href":"https://realnerdzw.github.io/GuideFlow/packages/analytics"}],["meta",{"property":"og:url","content":"https://realnerdzw.github.io/GuideFlow/packages/analytics"}],["meta",{"property":"og:title","content":"@guideflow/analytics — GuideFlow.js"}],["meta",{"property":"og:description","content":"@guideflow/analytics — tour event collection with privacy controls, five transports, and deterministic A/B variant assignment for GuideFlow."}],["meta",{"name":"twitter:title","content":"@guideflow/analytics — GuideFlow.js"}],["meta",{"name":"twitter:description","content":"@guideflow/analytics — tour event collection with privacy controls, five transports, and deterministic A/B variant assignment for GuideFlow."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Packages\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/packages/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"Analytics\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/packages/analytics/\\"}]}"]]},"headers":[],"relativePath":"packages/analytics.md","filePath":"packages/analytics.md","lastUpdated":1786207781000}'),s={name:"packages/analytics.md"};function n(d,t,r,l,c,p){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="guideflow-analytics" tabindex="-1">@guideflow/analytics <a class="header-anchor" href="#guideflow-analytics" aria-label="Permalink to &quot;@guideflow/analytics&quot;">​</a></h1><p><strong>Tour event collection, transports, and deterministic A/B assignment.</strong></p><p><a href="https://www.npmjs.com/package/@guideflow/analytics" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/v/@guideflow/analytics.svg" alt="npm version"></a></p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @guideflow/core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @guideflow/analytics</span></span></code></pre></div><p>No vendor SDK is bundled. The vendor transports call a global (<code>window.posthog</code>, <code>window.mixpanel</code>, …) that your app initialises.</p><h2 id="key-exports" tabindex="-1">Key Exports <a class="header-anchor" href="#key-exports" aria-label="Permalink to &quot;Key Exports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Export</th><th>Kind</th><th>Description</th></tr></thead><tbody><tr><td><code>AnalyticsCollector</code></td><td>class</td><td>Subscribes to six tour events and fans them out to transports</td></tr><tr><td><code>PrivacyPolicy</code></td><td>class</td><td>The consent / DNT / scrubbing / sampling logic, usable standalone</td></tr><tr><td><code>PostHogTransport</code></td><td>class</td><td><code>window.posthog.capture()</code></td></tr><tr><td><code>MixpanelTransport</code></td><td>class</td><td><code>window.mixpanel.track()</code></td></tr><tr><td><code>AmplitudeTransport</code></td><td>class</td><td><code>window.amplitude.track()</code></td></tr><tr><td><code>SegmentTransport</code></td><td>class</td><td><code>window.analytics.track()</code></td></tr><tr><td><code>WebhookTransport</code></td><td>class</td><td>Batched <code>POST</code> of a JSON array</td></tr><tr><td><code>ExperimentEngine</code></td><td>class</td><td>Deterministic A/B variant assignment</td></tr></tbody></table><p>Exported types: <code>CollectorOptions</code>, <code>PrivacyOptions</code>, <code>AnalyticsEvent</code>, <code>AnalyticsTransport</code>, <code>WebhookTransportOptions</code>, <code>Variant</code>, <code>Experiment</code>, <code>ExperimentResult</code>.</p><h2 id="what-it-emits" tabindex="-1">What it emits <a class="header-anchor" href="#what-it-emits" aria-label="Permalink to &quot;What it emits&quot;">​</a></h2><p>Six events, and only these six:</p><p><code>guideflow.tour.started</code>, <code>guideflow.tour.completed</code>, <code>guideflow.tour.abandoned</code>, <code>guideflow.step.viewed</code>, <code>guideflow.step.exited</code>, <code>guideflow.step.skipped</code>.</p><h2 id="privacy-defaults" tabindex="-1">Privacy defaults <a class="header-anchor" href="#privacy-defaults" aria-label="Permalink to &quot;Privacy defaults&quot;">​</a></h2><p>Query strings and fragments are stripped from <code>url</code> and <code>referrer</code>, Do Not Track is honoured, and a list of sensitive property names is redacted. All of it is configurable through the <code>privacy</code> option. See <a href="/GuideFlow/guide/privacy">Privacy</a>.</p><h2 id="a-b-assignment-is-not-applied-for-you" tabindex="-1">A/B assignment is not applied for you <a class="header-anchor" href="#a-b-assignment-is-not-applied-for-you" aria-label="Permalink to &quot;A/B assignment is not applied for you&quot;">​</a></h2><p><code>ExperimentEngine</code> returns a variant. No GuideFlow API consumes it — branching on the value and recording which variant a user saw are application code. See <a href="/GuideFlow/guide/ab-testing">A/B Testing</a>.</p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://www.npmjs.com/package/@guideflow/analytics" target="_blank" rel="noreferrer">npm</a></li><li><a href="https://github.com/RealNerdZW/GuideFlow/tree/master/packages/analytics" target="_blank" rel="noreferrer">Source</a></li><li><a href="/GuideFlow/guide/analytics">Analytics Guide</a></li><li><a href="/GuideFlow/guide/ab-testing">A/B Testing Guide</a></li><li><a href="/GuideFlow/guide/privacy">Privacy</a></li></ul>',18)])])}const g=e(s,[["render",n]]);export{h as __pageData,g as default};
